package com.fasterxml.jackson.databind.ser.impl;

import com.fasterxml.jackson.annotation.ObjectIdGenerator;
import com.fasterxml.jackson.core.JsonGenerator;
import com.fasterxml.jackson.core.SerializableString;
import com.fasterxml.jackson.databind.SerializerProvider;
import java.io.*;
import java.io.IOException;
import java.math.*;
import java.util.*;
import org.junit.*;
import org.junit.Assert;
import org.junit.Before;
import org.junit.Test;
import org.mockito.Mockito;
import static org.junit.Assert.*;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.Mockito.when;

/**
 * Unit tests for WritableObjectId#generateId
 */
public class WritableObjectId_generateId_TriageGen1Test {

    private ObjectIdGenerator<?> mockGenerator;
    private WritableObjectId writableObjectId;

    @Before
    public void setUp() {
        mockGenerator = Mockito.mock(ObjectIdGenerator.class);
        writableObjectId = new WritableObjectId(mockGenerator);
    }





    @Test
    public void testGenerateId_ReturnsDifferentIdOnSubsequentCalls() {
        // Arrange
        Object inputPojo = new Object();
        String id1 = "id-1";
        String id2 = "id-2";
        when(mockGenerator.generateId(inputPojo)).thenReturn(id1).thenReturn(id2);

        // Act
        Object firstCall = writableObjectId.generateId(inputPojo);
        Object secondCall = writableObjectId.generateId(inputPojo);

        // Assert
        Assert.assertEquals("First call should return first generated ID", id1, firstCall);
        Assert.assertEquals("Second call should return second generated ID", id2, secondCall);
    }


}

